async function renderNotifications(){setPage('Notificações','ATIVIDADE');const rows=await api.notifications();$('#content').innerHTML=`<div class="section-head"><div><h2>Central de notificações</h2><p>${rows.filter(x=>!x.read).length} não lidas</p></div><button id="readAll" class="secondary">Marcar todas como lidas</button></div><section class="notifications">${rows.map(n=>{const social=/social|post|curti|publica/i.test(n.tipo||n.mensagem),chat=/mensagem|chat/i.test(n.tipo||n.mensagem);return `<article class="notification ${n.read?'':'unread'}"><span class="dot"></span><div><p>${esc(n.mensagem||n.tipo||'Nova atividade')}</p><time>${date(n.created_at)}</time>${n.tipo==='convite'?`<div class="notification-actions"><button class="primary" data-invite-answer="1" data-id="${esc(n.referencia_id)}">Aceitar</button><button class="secondary" data-invite-answer="0" data-id="${esc(n.referencia_id)}">Recusar</button></div>`:social?'<button class="secondary" data-go-notification="social">Ver publicação</button>':chat?`<button class="secondary" data-go-notification="chat" data-actor="${esc(n.actor_id||'')}">Abrir conversa</button>`:''}</div></article>`}).join('')||'<div class="empty">Nenhuma notificação.</div>'}</section>`;$('#readAll').onclick=async()=>{await api.markNotificationsRead();await renderNotifications()};$$('[data-invite-answer]').forEach(b=>b.onclick=async()=>{try{await api.respondInvite({inviteId:b.dataset.id,accept:b.dataset.inviteAnswer==='1'});await renderNotifications()}catch(e){toast(failure(e))}});$$('[data-go-notification]').forEach(b=>b.onclick=async()=>{if(b.dataset.goNotification==='chat'&&b.dataset.actor){const f=(await api.friends()).find(x=>String(x.id)===b.dataset.actor);if(f)state.chatFriend=f}navigate(b.dataset.goNotification)})}

const statusLabels={online:'Online',jogando:'Jogando',ausente:'Ausente',dnd:'Não incomodar',invisivel:'Invisível'};
function bannerData(value){let url=value||'',x=50,y=50,z=100;try{const u=new URL(url),params=new URLSearchParams(u.hash.slice(1)),v=params.get('bc-cover')?.split(',');if(v){x=Math.max(0,Math.min(100,Number(v[0])||0));y=Math.max(0,Math.min(100,Number(v[1])||0));z=Math.max(100,Math.min(250,Number(v[2])||100));params.delete('bc-cover');u.hash=params.toString();url=u.href}}catch{}return {url,x,y,z}}
function bannerSave(url,x,y,z){if(!url)return '';const u=new URL(bannerData(url).url),h=new URLSearchParams(u.hash.slice(1));h.set('bc-cover',[x,y,z].map(Math.round).join(','));u.hash=h.toString();return u.href}
async function renderProfile(userId=null){setPage(userId?'Perfil':'Meu perfil','IDENTIDADE');const p=await api.profile(userId||null);state.profileUser=userId||null;const own=String(p.id)===String(state.userId),cover=bannerData(p.banner_url);$('#content').innerHTML=`<section class="profile-card"><div class="profile-cover"><div class="profile-cover-art"></div></div><div class="profile-body"><img class="profile-avatar" data-private-src="${esc(p.avatar_url||'')}" src="brand.jpg" alt="Foto de perfil"><div class="profile-info"><h2>${esc(p.nome||p.slug||'Perfil')}</h2><small>@${esc(p.slug||'batcaverna')} · ${esc(statusLabels[p.status_personalizado]||p.status_personalizado||'Online')}</small><p>${esc(p.bio||'Ainda não adicionou uma bio.')}</p><div class="profile-stats"><span><b>${p.stats?.total||0}</b> títulos</span><span><b>${p.stats?.finished||0}</b> concluídos</span><span><b>${p.stats?.hours||0}h</b> jogadas</span></div></div><div class="profile-actions">${own?'<button class="primary" id="editProfile">Editar perfil</button>':'<button class="secondary" id="profileChat">Conversar</button>'}</div></div></section><div id="profileHighlights"></div><div id="profileCharts"></div>`;await hydrateMedia($('#content'));const art=$('.profile-cover-art');if(cover.url){art.style.backgroundImage=`url(${JSON.stringify(await signed(cover.url))})`;art.style.backgroundPosition=`${cover.x}% ${cover.y}%`;art.style.transform=`scale(${cover.z/100})`}$('#editProfile')?.addEventListener('click',()=>openProfileEditor(p).catch(e=>toast(failure(e))));$('#profileChat')?.addEventListener('click',async()=>{const f=(await api.friends()).find(x=>String(x.id)===String(p.id));if(f){state.chatFriend=f;navigate('chat')}});if(own){state.profile=p;$('#accountName').textContent=p.nome||p.slug;$('#accountStatus').textContent=statusLabels[p.status_personalizado]||'Online';$('#accountAvatar').dataset.privateSrc=p.avatar_url||'';hydrateMedia($('.topbar'));const highlight=$('#profileHighlights'),charts=$('#profileCharts');try{const [stats,rows]=await Promise.all([loadStats(),api.library('jogos')]);if(!charts.isConnected)return;charts.innerHTML=chart(stats);const games=rows.filter(x=>(p.jogos_destaque||[]).includes(x.nome));if(games.length){highlight.innerHTML=`<div class="section-head"><h2>Jogos em destaque</h2></div><div class="grid">${games.map(mediaCard).join('')}</div>`;hydrateCovers(highlight)}}catch(e){if(charts.isConnected)charts.innerHTML=`<div class="error-card">Estatísticas indisponíveis: ${esc(failure(e))}</div>`}}}
function fileData(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result));r.onerror=()=>reject(Error('Não foi possível ler a imagem.'));r.readAsDataURL(file)})}
async function cropAvatar(source,x,y,zoom){const img=new Image();img.src=source;await img.decode();const size=Math.min(img.width,img.height)/(zoom/100),canvas=document.createElement('canvas');canvas.width=canvas.height=512;canvas.getContext('2d').drawImage(img,(img.width-size)*x/100,(img.height-size)*y/100,size,size,0,0,512,512);return canvas.toDataURL('image/webp',.9)}
async function openProfileEditor(p){const games=await api.library('jogos'),cover=bannerData(p.banner_url),o=document.createElement('div');o.className='editor-overlay';o.innerHTML=`<form class="editor profile-editor"><header><div><small>PERSONALIZAÇÃO</small><h2>Editar perfil</h2></div><button type="button" class="icon-button" data-close>×</button></header><nav class="tabs editor-tabs"><button type="button" data-profile-tab="info" class="active">Informações</button><button type="button" data-profile-tab="appearance">Foto e capa</button><button type="button" data-profile-tab="highlights">Destaques</button></nav><div data-profile-panel="info" class="editor-grid"><label>Nome público<input name="name" maxlength="40" required value="${esc(p.nome||'')}"></label><label>Status<select name="status">${Object.entries(statusLabels).map(([k,l])=>`<option value="${k}" ${k===p.status_personalizado?'selected':''}>${l}</option>`).join('')}</select></label><label class="wide">Bio<textarea name="bio" maxlength="280">${esc(p.bio||'')}</textarea></label><label class="wide">Steam ID<input name="steamId" pattern="[0-9]{17}" value="${esc(p.steam_id||'')}"></label></div><section data-profile-panel="appearance" hidden><div class="banner-preview"><div class="banner-preview-art"></div></div><div class="avatar-preview"><img src="brand.jpg" alt="Prévia da foto"></div><div class="editor-grid"><label>Enviar foto<input name="avatarFile" type="file" accept="image/png,image/jpeg,image/webp"></label><label>Enviar capa<input name="bannerFile" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="wide">URL da foto<input name="avatar" type="url" value="${esc(p.avatar_url||'')}"></label><label class="wide">URL da capa<input name="banner" type="url" value="${esc(cover.url)}"></label>${[['coverX','Posição horizontal da capa',cover.x,0,100],['coverY','Posição vertical da capa',cover.y,0,100],['coverZoom','Zoom da capa',cover.z,100,250],['avatarX','Posição horizontal da foto',50,0,100],['avatarY','Posição vertical da foto',50,0,100],['avatarZoom','Zoom da foto',100,100,250]].map(([k,l,v,min,max])=>`<label>${l} <output data-range="${k}">${v}%</output><input name="${k}" type="range" min="${min}" max="${max}" value="${v}"></label>`).join('')}</div><div class="preview-actions"><button type="button" class="secondary" id="centerImages">Centralizar imagens</button><button type="button" class="secondary" id="removeBanner">Remover capa</button><button type="button" class="secondary" id="removeAvatar">Remover foto</button></div></section><section data-profile-panel="highlights" hidden><h3>Jogos em destaque</h3><p class="muted">Selecione até 8 jogos da biblioteca.</p><div class="highlight-pick">${games.map(g=>`<label><input name="games" type="checkbox" value="${esc(g.nome)}" ${(p.jogos_destaque||[]).includes(g.nome)?'checked':''}>${esc(g.nome)}</label>`).join('')||'<p>Adicione jogos à biblioteca para escolher seus destaques.</p>'}</div></section><footer><span></span><div><button type="button" class="secondary" data-close>Cancelar</button><button class="primary">Salvar</button></div></footer><p class="form-error" role="status"></p></form>`;document.body.appendChild(o);const f=o.querySelector('form');let draftAvatar='',draftBanner='',avatarSource='',previewSequence=0;const close=()=>o.remove();o.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);o.onclick=e=>{if(e.target===o)close()};o.querySelectorAll('[data-profile-tab]').forEach(b=>b.onclick=()=>{o.querySelectorAll('[data-profile-panel]').forEach(el=>el.hidden=el.dataset.profilePanel!==b.dataset.profileTab);o.querySelectorAll('[data-profile-tab]').forEach(el=>el.classList.toggle('active',el===b))});async function preview(){const seq=++previewSequence;f.querySelectorAll('[data-range]').forEach(out=>out.value=f.elements[out.dataset.range].value+'%');const banner=draftBanner||await signed(f.elements.banner.value),avatar=draftAvatar||await signed(f.elements.avatar.value);if(seq!==previewSequence||!f.isConnected)return;const art=f.querySelector('.banner-preview-art');art.style.backgroundImage=banner&&banner!=='brand.jpg'?`url(${JSON.stringify(banner)})`:'';art.style.backgroundPosition=`${f.elements.coverX.value}% ${f.elements.coverY.value}%`;art.style.transform=`scale(${Number(f.elements.coverZoom.value)/100})`;const img=f.querySelector('.avatar-preview img');avatarSource=avatar;img.src=avatar;img.style.objectPosition=`${f.elements.avatarX.value}% ${f.elements.avatarY.value}%`;img.style.transform=`scale(${Number(f.elements.avatarZoom.value)/100})`}
 f.oninput=e=>{if(e.target.name==='banner'){draftBanner='';f.elements.bannerFile.value=''}if(e.target.name==='avatar'){draftAvatar='';f.elements.avatarFile.value=''}preview().catch(()=>{})};f.onchange=async e=>{const input=e.target;if(!['avatarFile','bannerFile'].includes(input.name))return;try{const file=input.files[0];if(!file)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>10*1024*1024)throw Error('Escolha PNG, JPG ou WebP de até 10 MB.');const src=await fileData(file);if(input.name==='avatarFile')draftAvatar=src;else draftBanner=src;await preview()}catch(err){input.value='';f.querySelector('.form-error').textContent=failure(err)}};f.querySelector('#centerImages').onclick=()=>{for(const k of ['coverX','coverY','avatarX','avatarY'])f.elements[k].value=50;f.elements.coverZoom.value=f.elements.avatarZoom.value=100;preview()};f.querySelector('#removeBanner').onclick=()=>{draftBanner='';f.elements.banner.value='';f.elements.bannerFile.value='';preview()};f.querySelector('#removeAvatar').onclick=()=>{draftAvatar='';f.elements.avatar.value='';f.elements.avatarFile.value='';preview()};f.addEventListener('invalid',()=>o.querySelector('[data-profile-tab="info"]').click(),true);f.onsubmit=async e=>{e.preventDefault();const b=f.querySelector('button.primary'),err=f.querySelector('.form-error'),selected=[...f.querySelectorAll('[name="games"]:checked')].map(x=>x.value);if(selected.length>8){err.textContent='Selecione até oito jogos.';return}b.disabled=true;err.textContent='Salvando…';try{let banner=f.elements.banner.value,avatar=f.elements.avatar.value;if(draftBanner){const file=f.elements.bannerFile.files[0],r=await api.uploadProfile({name:'banner',mime:file.type,base64:draftBanner.split(',')[1]});banner=r.url}if(draftAvatar||Number(f.elements.avatarZoom.value)!==100||Number(f.elements.avatarX.value)!==50||Number(f.elements.avatarY.value)!==50){let source=draftAvatar;if(!source){if(!avatar)throw Error('Selecione uma foto antes de ajustar.');source=await api.coverImage(await signed(avatar))}const cropped=await cropAvatar(source,Number(f.elements.avatarX.value),Number(f.elements.avatarY.value),Number(f.elements.avatarZoom.value)),r=await api.uploadProfile({name:'avatar',mime:'image/webp',base64:cropped.split(',')[1]});avatar=r.url}await api.updateProfile({name:f.elements.name.value,bio:f.elements.bio.value,status:f.elements.status.value,steamId:f.elements.steamId.value,avatar,banner:bannerSave(banner,Number(f.elements.coverX.value),Number(f.elements.coverY.value),Number(f.elements.coverZoom.value)),games:selected,titleLevel:Number(f.elements.titleLevel?.value||p.titulo_destaque_nivel||0),achievements:f.elements.achievements?[...f.querySelectorAll('[name="achievements"]:checked')].map(x=>Number(x.value)):p.conquistas_destaque||[]});close();toast('Perfil atualizado.');await renderProfile()}catch(error){err.textContent=failure(error)}finally{b.disabled=false}};await preview()}

async function renderSettings(){setPage('Configurações','SUA CONTA');const p=JSON.parse(localStorage.getItem('bc-desktop-prefs')||'{}');const tabs=[['account','Conta'],['appearance','Aparência'],['notifications','Notificações'],['privacy','Privacidade'],['app','Aplicativo']];$('#content').innerHTML=`<div class="settings-layout"><aside class="settings settings-nav">${tabs.map(([k,l])=>`<button data-settings-tab="${k}" class="${state.settingsTab===k?'active':''}">${l}</button>`).join('')}</aside><section class="settings" id="settingsPanel"></section></div>`;$$('[data-settings-tab]').forEach(b=>b.onclick=()=>{state.settingsTab=b.dataset.settingsTab;renderSettings()});const panel=$('#settingsPanel');if(state.settingsTab==='account')panel.innerHTML=`<div class="settings-row"><div><strong>Sua conta</strong><small>${esc(state.email||'Conta autenticada')}</small></div><button class="secondary" id="changePassword">Alterar senha</button></div><div class="settings-row"><div><strong>Meu perfil</strong><small>Nome, bio, status, banner e Steam</small></div><button class="secondary" id="goProfile">Editar</button></div><div class="settings-row"><div><strong>Sair da conta</strong><small>Remove a sessão protegida deste computador</small></div><button class="danger" id="logoutButton">Sair</button></div>`;if(state.settingsTab==='appearance')panel.innerHTML=`<div class="settings-row"><div><strong>Modo compacto</strong><small>Reduz espaços e mostra mais conteúdo na tela.</small></div><button class="toggle ${p.compact?'on':''}" data-toggle="compact"></button></div><div class="settings-row"><div><strong>Reduzir animações</strong><small>Desativa transições visuais.</small></div><button class="toggle ${p.noAnimations?'on':''}" data-toggle="noAnimations"></button></div><div class="settings-row"><div><strong>Identidade da BatCaverna</strong><small>O logo personalizado do seu perfil é aplicado automaticamente.</small></div><span>Ativa</span></div>`;if(state.settingsTab==='notifications')panel.innerHTML=`<div class="settings-row"><div><strong>Central de notificações</strong><small>Mensagens, convites e interações abrem diretamente o conteúdo correspondente.</small></div><button class="secondary" id="goNotifications">Abrir</button></div>`;if(state.settingsTab==='privacy')panel.innerHTML=`<div class="settings-row"><div><strong>Dados privados</strong><small>A biblioteca e as conversas continuam protegidas pelo Supabase e pelas regras de amizade.</small></div><span>Protegidos</span></div><div class="settings-row"><div><strong>Amigos e bloqueios</strong><small>Gerencie as pessoas que podem acessar seu perfil.</small></div><button class="secondary" id="goFriends">Gerenciar</button></div>`;if(state.settingsTab==='app')panel.innerHTML=`<div class="settings-row"><div><strong>BatCaverna para Windows</strong><small>Aplicativo nativo, sem carregar o site.</small></div><span>v${esc(state.version)}</span></div><div class="settings-row"><div><strong>Atualizações</strong><small>Novas versões são compiladas automaticamente pelo GitHub.</small></div><span>Ativas</span></div>`;$$('[data-toggle]').forEach(b=>b.onclick=()=>{const key=b.dataset.toggle;savePref(key,!p[key]);renderSettings()});$('#logoutButton')?.addEventListener('click',async()=>{await api.logout();showLogin()});$('#goProfile')?.addEventListener('click',()=>{state.profileUser=null;navigate('profile')});$('#goNotifications')?.addEventListener('click',()=>navigate('notifications'));$('#goFriends')?.addEventListener('click',()=>navigate('friends'));$('#changePassword')?.addEventListener('click',openPassword)}
function openPassword(){const o=document.createElement('div');o.className='editor-overlay';o.innerHTML=`<form class="editor" style="max-width:460px"><header><h2>Alterar senha</h2><button type="button" class="icon-button" data-close>×</button></header><div class="editor-grid"><label class="wide">Senha atual<input name="current" type="password" required></label><label class="wide">Nova senha<input name="password" type="password" minlength="12" required></label><label class="wide">Confirmar<input name="confirm" type="password" minlength="12" required></label></div><footer><span></span><button class="primary">Salvar</button></footer><p class="form-error"></p></form>`;document.body.appendChild(o);const close=()=>o.remove();o.querySelector('[data-close]').onclick=close;o.querySelector('form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));if(d.password!==d.confirm){e.currentTarget.querySelector('.form-error').textContent='As senhas devem coincidir.';return}try{await api.changePassword({current:d.current,password:d.password});close();toast('Senha atualizada.')}catch(err){e.currentTarget.querySelector('.form-error').textContent=failure(err)}}}

$('#mainNav').onclick=e=>{const b=e.target.closest('[data-view]');if(b){if(b.dataset.view==='profile')state.profileUser=null;navigate(b.dataset.view)}};$('.account').onclick=()=>{state.profileUser=null;navigate('profile')};$$('[data-auth]').forEach(b=>b.onclick=()=>setAuth(b.dataset.auth));
$('#loginForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,err=$('#loginError'),d=new FormData(form),b=form.querySelector('.primary');err.textContent='';b.disabled=true;b.textContent='Entrando…';try{await api.login({identifier:String(d.get('identifier')||'').trim(),password:String(d.get('password')||''),remember:d.get('remember')==='on'});showApp()}catch(failure){err.textContent=failureMessage(failure)}finally{b.disabled=false;b.textContent=b.dataset.idleLabel}};
$('#registerForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.primary'),err=f.querySelector('.error'),d=Object.fromEntries(new FormData(f));b.disabled=true;try{const r=await api.register(d);err.textContent=r.message||'Conta criada. Confira seu e-mail para confirmar.';err.style.color='#62dca1';f.reset()}catch(x){err.textContent=failure(x)}finally{b.disabled=false}};
$('#recoverForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('.primary'),err=f.querySelector('.error');b.disabled=true;try{await api.recover(f.elements.email.value);err.textContent='Se o e-mail estiver cadastrado, o link será enviado.';err.style.color='#62dca1'}catch(x){err.textContent=failure(x)}finally{b.disabled=false}};
applyPrefs();const initializeApp=()=>{api.state().then(s=>{state.version=s.version;state.userId=s.user?.id||'';state.email=s.user?.email||'';s.authenticated?showApp():showLogin()}).catch(showLogin)};if(document.readyState==='loading')window.addEventListener('DOMContentLoaded',initializeApp,{once:true});else initializeApp();

